+  /**
+   * Layer 1（arkts-immersive-safearea）：
+   * ① setWindowLayoutFullScreen(true) —— window 覆盖系统栏（背景穿透前提）
+   * ② setWindowSystemBarProperties —— 系统栏透明 + 浅色前景（状态栏区为深色主色变体，见 Index 标题栏上方露出区）
+   * ③ getWindowAvoidArea 测量安全区，写入 WindowModel（全工程唯一测量点）
+   * ④ windowSizeChange 监听 —— 折叠屏/分屏实时同步
+   */
+  private setupImmersiveWindow(windowStage: window.WindowStage): void {
+    windowStage.getMainWindow().then((mainWindow: window.Window) => {
+      const windowModel: WindowModel = WindowModel.connect();
+      mainWindow.setWindowLayoutFullScreen(true).catch((err: BusinessError) => {
+        hilog.error(DOMAIN, TAG, 'setWindowLayoutFullScreen failed: %{public}s', JSON.stringify(err));
+      });
+      mainWindow.setWindowSystemBarProperties({
+        statusBarColor: '#00000000',
+        statusBarContentColor: '#FFFFFF',
+        navigationBarColor: '#00000000'
+      }).catch((err: BusinessError) => {
+        hilog.error(DOMAIN, TAG, 'setWindowSystemBarProperties failed: %{public}s', JSON.stringify(err));
+      });
+      this.refreshAvoidArea(mainWindow, windowModel);
+      mainWindow.on('windowSizeChange', () => {
+        this.refreshAvoidArea(mainWindow, windowModel);
+      });
+    }).catch((err: BusinessError) => {
+      hilog.error(DOMAIN, TAG, 'getMainWindow failed: %{public}s', JSON.stringify(err));
+    });
+  }
+
+  /** 安全区测量：px → vp（vp = px / densityPixels），写入 WindowModel 4 字段 */
+  private refreshAvoidArea(mainWindow: window.Window, windowModel: WindowModel): void {
+    const density: number = display.getDefaultDisplaySync().densityPixels;
+    const systemArea: window.AvoidArea =
+      mainWindow.getWindowAvoidArea(window.AvoidAreaType.TYPE_SYSTEM);
+    const indicatorArea: window.AvoidArea =
+      mainWindow.getWindowAvoidArea(window.AvoidAreaType.TYPE_NAVIGATION_INDICATOR);
+    const cutoutArea: window.AvoidArea =
+      mainWindow.getWindowAvoidArea(window.AvoidAreaType.TYPE_CUTOUT);
+    windowModel.windowTopPadding = systemArea.topRect.height / density;
+    windowModel.windowBottomPadding = indicatorArea.bottomRect.height / density;
+    windowModel.cutoutTopPadding = cutoutArea.topRect.height / density;
+    windowModel.windowWidth = mainWindow.getWindowProperties().windowRect.width / density;
+  }
 }
